import{_ as i,l as o,o as a,c,v as s,p as r,x as t,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"发送路径与 qdisc","description":"","frontmatter":{"title":"发送路径与 qdisc","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tx-path-qdisc.md","filePath":"cs/tx-path-qdisc.md","lastUpdated":1789023840000}'),u={name:"cs/tx-path-qdisc.md"};function _(f,e,h,q,b,m){const d=o("Mermaid");return a(),c("div",null,[e[1]||(e[1]=s('<h1 id="发送路径与-qdisc" tabindex="-1">发送路径与 qdisc <a class="header-anchor" href="#发送路径与-qdisc" aria-label="Permalink to &quot;发送路径与 qdisc&quot;">​</a></h1><div class="epigraph"><p>qdisc 是设备出口的排队规则：FIFO、fq_codel、HTB 等在把 sk_buff 交给驱动之前做整形、分类与丢包。</p><footer>—— 据 Linux tc 与 qdisc 文档；Gettys and Nichols 对 bufferbloat 的论述；Van Jacobson 对队列的背景</footer></div><p><a href="/cs/rx-path">上一课</a>走到套接字。<a href="/cs/sendfile-splice">sendfile</a> 从文件进 skb。缺口是 <strong>TX</strong>：<code>dev_queue_xmit</code>、流量控制、驱动 <code>ndo_start_xmit</code>，以及 bufferbloat 为何是队列问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无队列：突发被网卡环丢。无限队列：延迟爆炸（bufferbloat）。qdisc：默认 pfifo_fast 或 fq_codel，按 band 或流公平排队，Codel 控延迟。缺口：BQL（字节队列限制）让驱动环不要堆太多；TC 分类器把 skb 送进不同 class；与 <a href="/cs/blk-schedulers">blk 调度</a> 对照——一个整形包，一个整形 bio，不要混。本课不把 eBPF 分类器写成观测课。</p><p><span class="marginnote">锁：今日 xmit 常 per-queue；老的 <code>qdisc_lock</code> 是历史。GSO 在出队后切，避免 qdisc 按大包不公平。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>sendmsg</code> → TCP 分段策略 → <code>ip_output</code> → POSTROUTING → <code>dev_queue_xmit</code> → qdisc <code>enqueue</code>。设备空闲则 <code>dequeue</code> 到驱动。拥塞：qdisc 丢或标记 ECN。对照 NAPI：TX 完成中断会 <code>net_tx_action</code> 再拉队列。对照 <a href="/cs/cgroups">cgroup</a>：net_cls/net_prio 给 skb 打类。</p>',8)),(a(),r(p,null,{default:t(()=>[n(d,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOCK%5B%22sendmsg%22%5D%20--%3E%20IP%5B%22IP%20%E8%BE%93%E5%87%BA%22%5D%0A%20%20IP%20--%3E%20QD%5B%22qdisc%20%E5%85%A5%E9%98%9F%22%5D%0A%20%20QD%20--%3E%20DRV%5B%22ndo_start_xmit%22%5D%0A%20%20DRV%20--%3E%20RING%5B%22%E7%BD%91%E5%8D%A1%E5%8F%91%E9%80%81%E7%8E%AF%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>qdisc 把「共享出口」收成可策略对象：延迟、公平、限速。没有它，多流 TCP 会在驱动环里互相伤害。不要写成 ISP 计费。与 GRO：收侧聚合，发侧整形，方向相反。</p><p>失败：<code>ENOBUFS</code>/<code>EAGAIN</code> 在套接字层因 sndbuf 或 qdisc 满——下一课背压。</p><p>实现上：BQL 按完成速率限制驱动环字节，减轻 bufferbloat。GSO 包在出队后切，以免一个 64K 逻辑包占满 band。锁less 的 pfifo 适合极高 PPS 的内部口。 读法上只引用<a href="/cs/rx-path">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>发送路径与 qdisc</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 HTB 层级实验。不保证无线 mac80211 的 qdisc 形状。下一课套接字自己的缓冲与窗口如何反过来压应用。</p><p>版本字段会变，课序钉的是机制对象「发送路径与 qdisc」，不是某一主线内核的结构体名。 后课默认：出口经 qdisc 再进驱动。sk 的 rcv/snd 缓冲如何限制未读/未确认字节，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TX 经 qdisc 整形再交给驱动。</li><li>BQL 与 Codel 对抗无界延迟。</li><li>套接字缓冲与背压是下一课。</li><li>出处：Linux tc；Gettys/Nichols bufferbloat；Benvenuti。</li></ul>',11))])}const P=i(u,[["render",_]]);export{T as __pageData,P as default};
